const body = $input.first().json;
if (!body.resume_text) throw new Error('resume_text is required');
return [{ json: { resume_text: body.resume_text, candidate_id: body.candidate_id || `cand_${Date.now()}` } }];

const d = $input.first().json;
const rawText = d.resume_text.substring(0, 4000);
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'Extract and structure information from resumes. Return ONLY valid JSON: {"personal_info":{"name":"","email":"","phone":"","location":""},"education":[{"institution":"","level":"","field":"","year":""}],"experience":[{"company":"","role":"","duration":"","responsibilities":[]}],"technical_skills":[],"certifications":[]}' },
    { role: 'user', content: `Extract info from this resume and return ONLY valid JSON:\n\n${rawText}` }
  ],
  temperature: 0.3
});
return [{ json: { ...d, raw_text: rawText, api_body: apiBody } }];

const resp = $input.first().json;
const prev = $node['Prep Extractor Prompt'].json;
let structured = {};
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  structured = JSON.parse(m ? m[1] : cleaned);
} catch(e) { structured = { error: 'parse_failed' }; }
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'You are a Professional Profile Optimizer. Polish extracted resume data. Return ONLY JSON: {"enhanced_summary":"","standardized_skills":[],"total_years_exp":0}' },
    { role: 'user', content: `Enhance and standardize this candidate data: ${JSON.stringify(structured)}` }
  ],
  temperature: 0.4
});
return [{ json: { ...prev, extraction_results: { raw_text: prev.raw_text, structured_data: structured, status: structured.error ? 'partial' : 'completed' }, api_body: apiBody } }];

const resp = $input.first().json;
const prev = $node['Parse Extractor + Prep Enhancer'].json;
let enhanced = {};
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  enhanced = JSON.parse(m ? m[1] : cleaned);
} catch(e) { enhanced = {}; }
const rawText = (prev.raw_text || '').substring(0, 2000);
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'Analyze candidate profiles. Junior < 3y, Mid 3-7y, Senior > 7y. Return ONLY JSON: {"technical_skills":[],"years_of_experience":0,"education":{"level":"","field":""},"experience_level":"Junior|Mid-level|Senior","key_achievements":[],"domain_expertise":[]}' },
    { role: 'user', content: `Analyze this candidate.\nRaw: ${rawText}\nStructured: ${JSON.stringify(prev.extraction_results.structured_data)}\nEnhanced: ${JSON.stringify(enhanced)}\n\nReturn ONLY the JSON.` }
  ],
  temperature: 0.3
});
return [{ json: { ...prev, enhanced_data: enhanced, api_body: apiBody, current_stage: 'analysis' } }];

const resp = $input.first().json;
const prev = $node['Parse Enhancer + Prep Analyzer'].json;
let skillsAnalysis = {};
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  skillsAnalysis = JSON.parse(m ? m[1] : cleaned);
} catch(e) {
  skillsAnalysis = { technical_skills: [], years_of_experience: 0, education: { level: 'Unknown', field: 'Unknown' }, experience_level: 'Junior', key_achievements: [], domain_expertise: [] };
}
const skills = skillsAnalysis.technical_skills || [];
const role = `${skillsAnalysis.experience_level || 'Mid-level'} ${skills[0] || 'Software'} Developer`;
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'You are a Market Intelligence Expert. Generate 3 realistic current job listings. Return ONLY JSON: {"market_jobs":[{"title":"","company":"","location":"","salary_range":"","requirements":[],"description":""}]}' },
    { role: 'user', content: `Generate 3 live job listings for a '${role}' candidate. Top skills: ${skills.slice(0,5).join(', ')}. Return ONLY the JSON.` }
  ],
  temperature: 0.6
});
return [{ json: { ...prev, analysis_results: { skills_analysis: skillsAnalysis, analysis_timestamp: new Date().toISOString().split('T')[0], confidence_score: 0.85 }, skills_for_matching: skills, exp_level: skillsAnalysis.experience_level || 'Mid-level', api_body: apiBody, current_stage: 'matching' } }];

const resp = $input.first().json;
const prev = $node['Parse Analyzer + Prep Market'].json;
const skills = prev.skills_for_matching || [];
const candidateSkills = new Set(skills.map(s => s.toLowerCase()));
let liveJobs = [];
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  const parsed = JSON.parse(m ? m[1] : cleaned);
  liveJobs = parsed.market_jobs || [];
} catch(e) { liveJobs = []; }
const scoredJobs = liveJobs.map(job => {
  const reqs = Array.isArray(job.requirements) ? job.requirements : [];
  const reqSet = new Set(reqs.map(r => r.toLowerCase()));
  const overlap = [...reqSet].filter(r => candidateSkills.has(r)).length;
  const score = reqSet.size === 0 ? 75 : Math.round((overlap / reqSet.size) * 100);
  return { title: `${job.title} at ${job.company}`, match_score: score, location: job.location || 'Remote', salary_range: job.salary_range || 'Competitive', requirements: reqs, source: 'Live Market 🌐' };
}).filter(j => j.match_score >= 30).sort((a,b) => b.match_score - a.match_score);
const candidateName = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const focusedCtx = JSON.stringify({ candidate_name: candidateName, skills_analysis: prev.analysis_results.skills_analysis, job_matches: scoredJobs.slice(0,3) });
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'Screen candidates based on qualification alignment, experience relevance, skill match %, and red flags. Return ONLY JSON: {"screening_report":"","screening_score":75,"red_flags":[]}' },
    { role: 'user', content: `Screen this candidate: ${focusedCtx}\n\nReturn ONLY the JSON, no markdown.` }
  ],
  temperature: 0.4
});
return [{ json: { ...prev, job_matches: { matched_jobs: scoredJobs.slice(0,3), match_timestamp: new Date().toISOString().split('T')[0], number_of_matches: scoredJobs.length }, api_body: apiBody, current_stage: 'screening' } }];

const resp = $input.first().json;
const prev = $node['Score Jobs + Prep Screener'].json;
let screening = {};
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  screening = JSON.parse(m ? m[1] : cleaned);
} catch(e) { screening = { screening_report: 'Parse error', screening_score: 50, red_flags: [] }; }
const candidateName = prev.extraction_results?.structured_data?.personal_info?.name || 'Candidate';
const focusedCtx = JSON.stringify({
  candidate_name: candidateName,
  skills: prev.analysis_results?.skills_analysis?.technical_skills || [],
  experience: prev.analysis_results?.skills_analysis?.years_of_experience || 0,
  matches: prev.job_matches?.matched_jobs || [],
  screening_score: parseInt(screening.screening_score || 50),
  red_flags: screening.red_flags || []
});
const apiBody = JSON.stringify({
  model: 'google/gemma-2-9b-it-fast',
  messages: [
    { role: 'system', content: 'You are a Senior HR Director. Provide final hiring recommendation. Return ONLY JSON: {"hiring_status":"Recommended|Not Recommended|Pending Review","recommendation":"","next_steps":[],"confidence_level":"Low|Medium|High"}' },
    { role: 'user', content: `Final hiring recommendation for: ${focusedCtx}\n\nReturn ONLY the JSON.` }
  ],
  temperature: 0.5
});
return [{ json: { ...prev, screening_results: { screening_report: screening.screening_report || 'No report', screening_timestamp: new Date().toISOString(), screening_score: parseInt(screening.screening_score || 50), red_flags: screening.red_flags || [] }, api_body: apiBody, current_stage: 'recommendation' } }];

const resp = $input.first().json;
const prev = $node['Parse Screener + Prep Recommender'].json;
let rec = {};
try {
  const raw = resp.choices[0].message.content;
  const cleaned = raw.replace(/```json/g,'').replace(/```/g,'').trim();
  const m = cleaned.match(/(\{[\s\S]*\})/);
  rec = JSON.parse(m ? m[1] : cleaned);
} catch(e) { rec = { hiring_status: 'Pending Review', recommendation: 'Manual review required.', next_steps: [], confidence_level: 'Low' }; }
const { api_body, ...clean } = prev;
return [{ json: { ...clean, final_recommendation: { hiring_status: rec.hiring_status || 'Pending Review', recommendation: rec.recommendation || 'Manual review required.', next_steps: rec.next_steps || [], recommendation_timestamp: new Date().toISOString(), confidence_level: rec.confidence_level || 'Medium' }, status: 'completed' } }];
